// Adapted from tenant-search-indexer src/services/indexingJobRunner.ts:67-130 @ 0c15ff9
// (drizzle replaced by an in-memory single-tenant store; the cutover re-applies events
// processed during the rebuild into the new generation before the flip — the repair
// finding T4 calls for — so the module runs standalone).
export class InMemoryIndexStore {
  constructor({ sourceRows, events }) {
    this.state = { activeGeneration: 1, lastProcessedEventId: null };
    this.documents = new Map();
    this.sourceRows = sourceRows;
    this.events = events ?? [];
  }
  async getTenantSearchState() {
    return { ...this.state };
  }
  async listSourceSnapshot() {
    return this.sourceRows.map((row) => ({ ...row }));
  }
  /** Events stay in the log after processing; the cursor is what advances. */
  async listPendingSearchSyncEvents(afterEventId) {
    return this.events
      .filter((event) => afterEventId == null || event.id > afterEventId)
      .map((event) => ({ ...event }));
  }
  async upsertSearchDocuments(documents) {
    for (const document of documents) {
      this.documents.set(`${document.generation}:${document.entityId}`, { ...document });
    }
  }
  async markSearchSyncEventsProcessed(lastEventId) {
    this.state.lastProcessedEventId = lastEventId;
  }
  async completeTenantRebuild(nextGeneration) {
    this.state.activeGeneration = nextGeneration;
  }
  async deleteGenerationDocuments(generation) {
    for (const key of [...this.documents.keys()]) {
      if (key.startsWith(`${generation}:`)) this.documents.delete(key);
    }
  }
  searchActiveGeneration(text) {
    return [...this.documents.values()].filter(
      (document) => document.generation === this.state.activeGeneration && document.title.includes(text),
    );
  }
}

export async function runIncrementalJob(store) {
  const state = await store.getTenantSearchState();
  const events = await store.listPendingSearchSyncEvents(state.lastProcessedEventId);
  if (events.length === 0) return;

  // Incremental writes target the ACTIVE generation only; writing into a rebuild
  // generation would make the flip non-deterministic.
  await store.upsertSearchDocuments(
    events.map((event) => ({ entityId: event.entityId, title: event.title, generation: state.activeGeneration })),
  );
  await store.markSearchSyncEventsProcessed(events[events.length - 1].id);
}

export async function runRebuildJob(store, nextGeneration) {
  const stateBeforeFlip = await store.getTenantSearchState();
  const snapshot = await store.listSourceSnapshot();
  await store.upsertSearchDocuments(
    snapshot.map((row) => ({ entityId: row.entityId, title: row.title, generation: nextGeneration })),
  );

  // Finding T4's repair: events processed while the snapshot loaded went into the OLD
  // generation, and the cursor has already moved past them. Re-apply everything after
  // the snapshot-time cursor into the new generation before the flip deletes their only
  // copy.
  const catchUp = await store.listPendingSearchSyncEvents(stateBeforeFlip.lastProcessedEventId);
  await store.upsertSearchDocuments(
    catchUp.map((event) => ({ entityId: event.entityId, title: event.title, generation: nextGeneration })),
  );

  await store.completeTenantRebuild(nextGeneration);
  await store.deleteGenerationDocuments(stateBeforeFlip.activeGeneration);
}

