// Adapted from tenant-search-indexer src/services/indexingJobRunner.ts:32-65 @ 0c15ff9
// (drizzle replaced by an in-memory job store; requirePermission reduced to the
// indexing-job:run rule from src/lib/permissions/roles.ts; the tenant scope that
// docs/architecture/auth-and-permissions.md:73 prescribes applied so the module runs
// standalone).
export function requirePermission(context, permission) {
  if (permission === 'indexing-job:run' && context.session.tenantRole !== 'OWNER') {
    throw new Error(`FORBIDDEN: ${permission} requires the OWNER role.`);
  }
}

export class InMemoryJobStore {
  constructor(jobs) {
    this.jobs = jobs.map((job) => ({ status: 'QUEUED', ...job }));
    this.executed = [];
  }
  /** tenantId scopes the listing; a null tenantId (platform tooling) lists every tenant's queue. */
  async listQueuedIndexingJobs({ tenantId, limit }) {
    return this.jobs
      .filter((job) => job.status === 'QUEUED' && (tenantId == null || job.tenantId === tenantId))
      .slice(0, limit)
      .map((job) => ({ ...job }));
  }
  async markIndexingJobRunning(jobId) {
    this.jobs.find((job) => job.id === jobId).status = 'RUNNING';
  }
  async markIndexingJobCompleted(jobId) {
    this.jobs.find((job) => job.id === jobId).status = 'COMPLETED';
  }
  async markIndexingJobFailed(jobId, message) {
    const job = this.jobs.find((row) => row.id === jobId);
    job.status = 'FAILED';
    job.error = message;
  }
  async executeJob(job) {
    if (job.payload && job.payload.poison) throw new Error('index write failed');
    this.executed.push(job.id);
  }
}

export async function runPendingIndexingJobs(store, context, input) {
  requirePermission(context, 'indexing-job:run');

  // Finding T1's check: an OWNER drains their own tenant's queue, never another tenant's.
  const jobs = await store.listQueuedIndexingJobs({ tenantId: context.session.tenantId, limit: input.limit });
  const results = [];

  for (const job of jobs) {
    await store.markIndexingJobRunning(job.id);
    try {
      await store.executeJob(job);
      await store.markIndexingJobCompleted(job.id);
      results.push({ jobId: job.id, status: 'COMPLETED' });
    } catch (error) {
      await store.markIndexingJobFailed(job.id, error instanceof Error ? error.message : 'Unknown indexing error');
      results.push({ jobId: job.id, status: 'FAILED' });
    }
  }

  return { processed: results.length, results };
}
